package com.datalens.conversation;
import java.util.*;import java.time.Instant;
import org.junit.jupiter.api.*;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;
import com.datalens.permission.PermissionService;import com.datalens.identity.CurrentActor;import com.datalens.semantic.*;import com.datalens.semantic.SemanticModels.*;import com.datalens.datasource.SourceModels.Field;import com.datalens.model.*;import com.datalens.chart.*;import com.datalens.query.*;import com.datalens.audit.AuditService;import tools.jackson.databind.json.JsonMapper;import jakarta.validation.Validation;import static com.datalens.conversation.ConversationModels.*;
class ConversationServiceTest {
 final ConversationStore store=mock(ConversationStore.class);final PermissionService permissions=mock(PermissionService.class);final SemanticService semantics=mock(SemanticService.class);final ModelGateway model=mock(ModelGateway.class);final ChartService charts=mock(ChartService.class);final QueryService queries=mock(QueryService.class);final AuditService audit=mock(AuditService.class);final JsonMapper json=JsonMapper.builder().build();final CurrentActor actor=new CurrentActor(1,"alice","USER",1);
 final ChartSemanticAuthorization provenance=new ChartSemanticAuthorization(semantics);
 final ConversationService service=new ConversationService(store,permissions,semantics,model,charts,provenance,queries,json,Validation.buildDefaultValidatorFactory().getValidator(),audit);
 final ConversationStore.Row row=new ConversationStore.Row("conversation",1,"subject","Title",0);
 static Publication publication(long version){var f=new BusinessField("day","Day",List.of(),new Field("orders","day"),"DATE","day","PUBLIC");var m=new Metric("sales","Sales",List.of(),"COUNT(day)","reviewed","day","owner","count","daily","ignore","UTC",List.of("day"),"SELECT COUNT(day) AS sales FROM orders WHERE day >= ? AND day < ?",List.of(new QueryModels.Parameter("DATE","2026-01-01"),new QueryModels.Parameter("DATE","2026-02-01")),new TimeParameters(0,1,"America/New_York","DATE"));return new Publication("subject",version,new Document(List.of(f),List.of(m),List.of(),List.of(),List.of()),"a".repeat(64),"scope",1,1,Instant.EPOCH,Instant.EPOCH);}
 ConversationStore.Stored turn(String id,String question,String status,String def,String preview,String task){return new ConversationStore.Stored(id,"conversation",id.equals("previous")?1:2,question,status,null,def,null,preview,task,null,null,Instant.EPOCH);}
 ChartModels.Definition definition(){var p=publication(1);var m=p.document().metrics().getFirst();return new ChartModels.Definition("subject",m.sql(),m.parameters(),new ChartModels.TimeRule("NONE",null,null,null,null),ChartSemanticAuthorization.description(m),new ChartModels.Spec("TABLE",null,List.of()),new ChartModels.SemanticBinding(1,p.digest(),p.scopeFingerprint(),m.id()));}
 @BeforeEach void setup(){when(permissions.current()).thenReturn(actor);when(semantics.retrievePublished(actor,"subject")).thenReturn(publication(1));when(store.get("conversation")).thenReturn(row);when(store.turns("conversation")).thenReturn(List.of());}
 @Test void foreignConversationNeverReadsHistory(){when(store.get("conversation")).thenReturn(new ConversationStore.Row("conversation",2,"subject","Secret",0));assertThatThrownBy(()->service.detail("conversation")).isInstanceOf(org.springframework.security.access.AccessDeniedException.class);verify(store,never()).turns(any());verifyNoInteractions(model,charts);}
 @Test void forgedTurnIsScopedByConversation(){when(store.turn("conversation","foreign")).thenThrow(ConversationStore.missing());assertThatThrownBy(()->service.result("conversation","foreign")).isInstanceOf(com.datalens.common.web.DomainException.class);verifyNoInteractions(charts,model);}
 @Test void duplicatePlanningRequestNeverCallsProvider(){var t=turn("turn","sales","PLANNING",null,null,null);when(store.admit(eq(1L),eq("conversation"),any())).thenReturn(new ConversationStore.Admission(t,false));when(store.turn("conversation","turn")).thenReturn(t);assertThat(service.send("conversation",new Send("sales",0,"request_key"),"trace").status()).isEqualTo("PLANNING");verifyNoInteractions(model,charts);}
 @Test void noPreviousMetricRequiresClarificationWithoutProvider(){var t=turn("turn","改成上个月","PLANNING",null,null,null);when(store.admit(eq(1L),eq("conversation"),any())).thenReturn(new ConversationStore.Admission(t,true));when(store.turn("conversation","turn")).thenReturn(t);service.send("conversation",new Send("改成上个月",0,"request_key"),"trace");verify(store).clarify(eq("turn"),contains("先选择"),isNull());verifyNoInteractions(model,charts);}
 @Test void previousMonthKeepsSqlMetricAndReviewedParameters(){var old=definition();var previous=turn("previous","sales","READY",json.writeValueAsString(old),null,null);var t=turn("turn","改成上个月","PLANNING",null,null,null);when(store.turns("conversation")).thenReturn(List.of(previous,t));when(store.admit(eq(1L),eq("conversation"),any())).thenReturn(new ConversationStore.Admission(t,true));when(store.turn("conversation","turn")).thenReturn(t);when(charts.preview(any(),eq("trace"))).thenAnswer(inv->new ChartModels.Preview("preview",((ChartModels.PreviewInput)inv.getArgument(0)).definition(),"task"));service.send("conversation",new Send("改成上个月",0,"request_key"),"trace");verifyNoInteractions(model);verify(charts).preview(argThat(p->p.definition().sql().equals(old.sql())&&p.definition().parameters().equals(old.parameters())&&p.definition().semanticBinding().equals(old.semanticBinding())&&p.definition().timeRule().kind().equals("LAST_MONTH")),eq("trace"));}
 @Test void republishedMetricBlocksHistory(){when(semantics.retrievePublished(actor,"subject")).thenReturn(publication(2));var t=turn("turn","sales","READY",json.writeValueAsString(definition()),null,null);when(store.turns("conversation")).thenReturn(List.of(t));assertThatThrownBy(()->service.detail("conversation")).isInstanceOf(org.springframework.security.access.AccessDeniedException.class);verifyNoInteractions(model,charts);}
 @Test void explicitConfirmationRequired(){assertThatThrownBy(()->service.save("conversation","turn",new ConversationModels.Save("Chart",false),"trace")).isInstanceOf(com.datalens.common.web.DomainException.class);verifyNoInteractions(charts);}
 @Test void noDataUsesActualEmptyRows(){var t=turn("turn","sales","QUERYING",json.writeValueAsString(definition()),"preview","task");var done=turn("turn","sales","NO_DATA",t.definition(),"preview","task");when(store.turn("conversation","turn")).thenReturn(t,done);when(queries.get("task")).thenReturn(new QueryModels.TaskView("task","subject","SUCCEEDED",null,Instant.EPOCH,Instant.EPOCH,1L,false));when(charts.previewResult("preview")).thenReturn(new QueryModels.Result(List.of(),List.of(),false,1000));assertThat(service.turn("conversation","turn").status()).isEqualTo("NO_DATA");verify(store).finish("turn","NO_DATA",null);verifyNoInteractions(model);}
 @Test void modelFailurePersistsFailureAndDoesNotRunQuery(){var t=turn("turn","sales","PLANNING",null,null,null);when(store.admit(eq(1L),eq("conversation"),any())).thenReturn(new ConversationStore.Admission(t,true));when(model.generate(any(),any())).thenThrow(new com.datalens.common.web.DomainException(504,"MODEL_TIMEOUT","timeout"));assertThatThrownBy(()->service.send("conversation",new Send("sales",0,"request_key"),"trace")).isInstanceOf(com.datalens.common.web.DomainException.class);verify(store).finish("turn","FAILED","MODEL_TIMEOUT");verifyNoInteractions(charts);}
 @Test void withdrawnSubjectCannotLeakListTitles(){when(store.list(1)).thenReturn(List.of(row));when(semantics.retrievePublished(actor,"subject")).thenThrow(new com.datalens.common.web.DomainException(404,"SEMANTIC_NOT_PUBLISHED","missing"));assertThat(service.list()).isEmpty();}
 @Test void recoveryDoesNotRetryProvider(){service.recover();verify(store).recover();verifyNoInteractions(model,charts);}
 @Test void losingExecutorLeaseCannotRecoverLivePlanning(){doThrow(new IllegalStateException("lease lost")).when(queries).requireAvailable();assertThatThrownBy(service::recover).isInstanceOf(IllegalStateException.class);verify(store,never()).recover();}
 @Test void completedTurnRetainsTruncationMetadata(){var t=turn("turn","sales","READY",json.writeValueAsString(definition()),"preview","task");when(store.turn("conversation","turn")).thenReturn(t);when(queries.get("task")).thenReturn(new QueryModels.TaskView("task","subject","SUCCEEDED",null,Instant.EPOCH,Instant.EPOCH,1L,true));assertThat(service.turn("conversation","turn").truncated()).isTrue();}
 @Test void invalidChartTerminatesTurnRatherThanStayingQuerying(){var t=turn("turn","sales","QUERYING",json.writeValueAsString(definition()),"preview","task");when(store.turn("conversation","turn")).thenReturn(t);when(queries.get("task")).thenReturn(new QueryModels.TaskView("task","subject","SUCCEEDED",null,Instant.EPOCH,Instant.EPOCH,1L,false));when(charts.previewResult("preview")).thenThrow(new com.datalens.common.web.DomainException(422,"CHART_INVALID","invalid"));service.turn("conversation","turn");verify(store).finish("turn","FAILED","CHART_INVALID");}
}
